// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type MinimalistExplainerProps = Record<string, any>;

// Deterministic pseudo-random generator
const pseudoRand = (i: number) => ((i * 29.3847) % 100) / 100;

// Quadratic Bezier interpolation
const getBezierPoint = (
  t: number,
  p0: { x: number; y: number },
  p1: { x: number; y: number },
  p2: { x: number; y: number }
) => {
  const x =
    Math.pow(1 - t, 2) * p0.x + 2 * (1 - t) * t * p1.x + Math.pow(t, 2) * p2.x;
  const y =
    Math.pow(1 - t, 2) * p0.y + 2 * (1 - t) * t * p1.y + Math.pow(t, 2) * p2.y;
  return { x, y };
};

const CSSPlayTriangle: React.FC<{ color: string }> = ({ color }) => (
  <div
    style={{
      width: 0,
      height: 0,
      borderTop: "6px solid transparent",
      borderBottom: "6px solid transparent",
      borderLeft: `10px solid ${color}`,
      transform: "translateX(2px)",
    }}
  />
);

const MinimalistExplainer: React.FC<MinimalistExplainerProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 15,
  primaryColor = "#aa00e6",
  secondaryColor = "#ffffff",
  hookText = "Why average videos fail...",
  supplyText = "Too much supply",
  demandText = "Even with demand...",
  coreMessageLine1 = "Low Supply + High Demand",
  coreMessageLine2 = "= Average Wins",
  finalPunchLine1 = "Find the gap.",
  finalPunchLine2 = "Win without being the best.",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Global Grid & Hero Box Setup
  const boxes = useMemo(() => {
    const cCount = 10;
    const rCount = 16;
    const bW = width * 0.05; // 54px on 1080
    const bH = bW * (16 / 9); // 96px on 1080
    const colStep = width / cCount;
    const rowStep = height / rCount;

    return Array.from({ length: cCount * rCount }).map((_, i) => {
      const c = i % cCount;
      const r = Math.floor(i / cCount);
      const x = c * colStep + (colStep - bW) / 2;
      const y = r * rowStep + (rowStep - bH) / 2;
      const isHero = i === 118; // Specific box that will become the sweet spot
      const randVal = pseudoRand(i);
      const phase = isHero ? 3 : randVal < 0.3 ? 1 : 2;
      return { id: i, x, y, phase, rand: randVal, isHero, bW, bH };
    });
  }, [width, height]);

  // Demand Dots Setup
  const demandDots = useMemo(() => {
    return Array.from({ length: 45 }).map((_, i) => ({
      x: pseudoRand(i + 100) * width,
      y: pseudoRand(i + 200) * height,
      delay: pseudoRand(i + 300) * 30,
    }));
  }, [width, height]);

  // Graph Coordinates
  const graphStartX = width * 0.15;
  const graphEndX = width * 0.85;
  const graphTopY = height * 0.4;
  const graphBottomY = height * 0.7;

  const P0 = { x: graphStartX + 50, y: graphTopY + 50 };
  const P1 = { x: graphStartX + 150, y: graphBottomY - 50 };
  const P2 = { x: graphEndX - 50, y: graphBottomY - 50 };

  // -----------------------------------------------------
  // Animations
  // -----------------------------------------------------

  const hero = boxes.find((b) => b.isHero)!;

  // Hero Box Movement & Scaling
  const heroIntroScale = spring({
    frame: frame - 15,
    fps,
    config: { damping: 14 },
  });
  const heroX_phase1 = interpolate(frame, [240, 260], [hero.x, P2.x - hero.bW / 2], {
    easing: Easing.bezier(0.25, 0.1, 0.25, 1),
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  const heroY_phase1 = interpolate(frame, [240, 260], [hero.y, P2.y - hero.bH / 2], {
    easing: Easing.bezier(0.25, 0.1, 0.25, 1),
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  const curveProgress = interpolate(frame, [260, 310], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  const t = 1 - curveProgress;
  const bezierPoint = getBezierPoint(t, P0, P1, P2);

  const heroX = frame >= 260 ? bezierPoint.x - hero.bW / 2 : heroX_phase1;
  const heroY = frame >= 260 ? bezierPoint.y - hero.bH / 2 : heroY_phase1;

  const heroGlow = interpolate(frame, [280, 310], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const heroScaleNum = interpolate(frame, [280, 310], [1, 2], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const currentHeroScale = frame < 280 ? heroIntroScale : heroScaleNum;
  const heroIntroOp = interpolate(frame, [10, 25], [0, 1], {
    extrapolateRight: "clamp",
  });
  const scene4FadeOut = interpolate(frame, [330, 345], [1, 0], {
    extrapolateRight: "clamp",
  });

  // Graph Axes
  const axisProgress = spring({
    frame: frame - 240,
    fps,
    config: { damping: 15 },
  });
  const currentTopY = interpolate(axisProgress, [0, 1], [graphBottomY, graphTopY]);
  const currentEndX = interpolate(axisProgress, [0, 1], [graphStartX, graphEndX]);

  // Sweet Spot Text
  const ssScale = spring({
    frame: frame - 300,
    fps,
    config: { damping: 12 },
  });

  // Texts
  const textPills = [
    { text: hookText, start: 0, end: 55 },
    { text: supplyText, start: 60, end: 135 },
    { text: demandText, start: 140, end: 225 },
  ];

  // Final Sequence
  const coreScale = spring({ frame: frame - 330, fps });
  const coreOp = interpolate(frame, [330, 340, 380, 390], [0, 1, 1, 0], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  const closingScale = spring({ frame: frame - 390, fps });
  const closingOp = interpolate(frame, [390, 400], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  const pulseOp = interpolate(frame, [420, 440, 450], [0, 0.4, 0], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        fontFamily: interFamily,
        backgroundColor: bgColor,
        overflow: "hidden",
      }}
    >
      {/* Background Boxes */}
      {boxes.map((box) => {
        if (box.isHero) return null;

        const delay = box.phase === 1 ? box.rand * 30 : 60 + box.rand * 60;
        const boxIntroOp = interpolate(frame - delay, [0, 15], [0, 0.25], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });
        const boxFadeOut = interpolate(frame, [240, 255], [1, 0], {
          extrapolateRight: "clamp",
        });
        const boxScale = spring({
          frame: frame - delay,
          fps,
          config: { damping: 14 },
        });
        const baseGlow = interpolate(frame, [30, 60], [0, 0.4], {
          extrapolateRight: "clamp",
        });

        return (
          <div
            key={box.id}
            style={{
              position: "absolute",
              left: box.x,
              top: box.y,
              width: box.bW,
              height: box.bH,
              backgroundColor: secondaryColor,
              borderRadius: 6,
              opacity: boxIntroOp * boxFadeOut,
              transform: `scale(${boxScale})`,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              boxShadow: `0 0 8px 1px rgba(170, 0, 230, ${baseGlow})`,
              transition: "none",
            }}
          >
            <CSSPlayTriangle color="#000" />
          </div>
        );
      })}

      {/* Demand Dots */}
      {demandDots.map((dot, i) => {
        const dotScale = spring({
          frame: frame - 150 - dot.delay,
          fps,
          config: { damping: 10 },
        });
        const dotOp = interpolate(frame, [240, 255], [1, 0], {
          extrapolateRight: "clamp",
        });
        return (
          <div
            key={`dot-${i}`}
            style={{
              position: "absolute",
              left: dot.x,
              top: dot.y,
              width: 12,
              height: 12,
              backgroundColor: primaryColor,
              borderRadius: "50%",
              transform: `scale(${dotScale})`,
              opacity: dotOp,
              boxShadow: `0 0 10px ${primaryColor}`,
              transition: "none",
            }}
          />
        );
      })}

      {/* Graph Area */}
      <div style={{ position: "absolute", inset: 0, opacity: scene4FadeOut }}>
        <svg
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
          }}
        >
          <defs>
            <clipPath id="graph-clip">
              <rect x={bezierPoint.x} y={0} width={width} height={height} />
            </clipPath>
          </defs>

          <line
            x1={graphStartX}
            y1={graphBottomY}
            x2={graphStartX}
            y2={currentTopY}
            stroke={secondaryColor}
            strokeWidth={4}
          />
          <line
            x1={graphStartX}
            y1={graphBottomY}
            x2={currentEndX}
            y2={graphBottomY}
            stroke={secondaryColor}
            strokeWidth={4}
          />

          {frame >= 260 && (
            <path
              d={`M ${P0.x} ${P0.y} Q ${P1.x} ${P1.y} ${P2.x} ${P2.y}`}
              stroke={primaryColor}
              strokeWidth={8}
              fill="none"
              clipPath="url(#graph-clip)"
              style={{
                filter: `drop-shadow(0 0 15px ${primaryColor})`,
              }}
            />
          )}
        </svg>

        <div
          style={{
            position: "absolute",
            top: graphBottomY + 20,
            left: graphEndX - 60,
            color: secondaryColor,
            fontSize: 24,
            opacity: axisProgress,
            fontWeight: 600,
          }}
        >
          Supply
        </div>
        <div
          style={{
            position: "absolute",
            top: graphTopY - 40,
            left: graphStartX - 30,
            color: secondaryColor,
            fontSize: 24,
            opacity: axisProgress,
            fontWeight: 600,
          }}
        >
          Reward
        </div>

        {frame >= 300 && frame < 345 && (
          <div
            style={{
              position: "absolute",
              top: P0.y - 100,
              left: P0.x - 20,
              color: primaryColor,
              fontSize: 40,
              fontWeight: 800,
              transform: `scale(${ssScale})`,
              textShadow: `0 0 20px ${primaryColor}`,
            }}
          >
            Sweet Spot
          </div>
        )}
      </div>

      {/* Hero Box */}
      <div
        style={{
          position: "absolute",
          left: heroX,
          top: heroY,
          width: hero.bW,
          height: hero.bH,
          backgroundColor: secondaryColor,
          borderRadius: 6,
          opacity: heroIntroOp * scene4FadeOut,
          transform: `scale(${currentHeroScale})`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          boxShadow: `0 0 ${heroGlow * 40}px ${heroGlow * 15}px ${primaryColor}`,
          zIndex: 10,
          transition: "none",
        }}
      >
        <CSSPlayTriangle color="#000" />
      </div>

      {/* Text Pills */}
      {textPills.map((pill, i) => {
        const op = interpolate(
          frame,
          [pill.start, pill.start + 10, pill.end - 10, pill.end],
          [0, 1, 1, 0],
          { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
        );
        const scale = spring({
          frame: frame - pill.start,
          fps,
          config: { damping: 12 },
        });

        if (frame < pill.start || frame > pill.end) return null;

        return (
          <div
            key={`pill-${i}`}
            style={{
              position: "absolute",
              top: "50%",
              left: "50%",
              transform: `translate(-50%, -50%) scale(${scale})`,
              opacity: op,
              backgroundColor: backgroundColor,
              padding: "24px 48px",
              borderRadius: 50,
              color: secondaryColor,
              fontSize: 56,
              fontWeight: 800,
              whiteSpace: "nowrap",
              border: `3px solid #333`,
              zIndex: 20,
              boxShadow: `0 20px 40px rgba(0,0,0,0.5)`,
              transition: "none",
            }}
          >
            {pill.text}
          </div>
        );
      })}

      {/* Core Message */}
      {frame >= 330 && frame <= 390 && (
        <div
          style={{
            position: "absolute",
            top: "50%",
            left: "50%",
            transform: `translate(-50%, -50%) scale(${coreScale})`,
            opacity: coreOp,
            width: "90%",
            textAlign: "center",
            zIndex: 30,
          }}
        >
          <div
            style={{
              color: secondaryColor,
              fontSize: 64,
              fontWeight: 800,
              lineHeight: 1.2,
            }}
          >
            {coreMessageLine1}
          </div>
          <div
            style={{
              color: primaryColor,
              fontSize: 72,
              fontWeight: 900,
              marginTop: 24,
              textShadow: `0 0 30px ${primaryColor}`,
            }}
          >
            {coreMessageLine2}
          </div>
        </div>
      )}

      {/* Closing Punch */}
      {frame >= 390 && (
        <div
          style={{
            position: "absolute",
            top: "50%",
            left: "50%",
            transform: `translate(-50%, -50%) scale(${closingScale})`,
            opacity: closingOp,
            width: "90%",
            textAlign: "center",
            zIndex: 30,
          }}
        >
          <div
            style={{
              color: secondaryColor,
              fontSize: 72,
              fontWeight: 800,
              lineHeight: 1.2,
            }}
          >
            {finalPunchLine1}
          </div>
          <div
            style={{
              color: primaryColor,
              fontSize: 56,
              fontWeight: 700,
              marginTop: 32,
            }}
          >
            {finalPunchLine2}
          </div>
        </div>
      )}

      {/* Final Pulse Effect */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          backgroundColor: primaryColor,
          opacity: pulseOp,
          pointerEvents: "none",
          zIndex: 100,
          transition: "none",
        }}
      />
    </AbsoluteFill>
  );
};

export default MinimalistExplainer;